#include <bits/stdc++.h>
using namespace std;

void solve() {
  int n;
  cin >> n;
  map<int, int> cnt;
  for (int i = 0; i < n; i++) {
    int x;
    cin >> x;
    cnt[x]++;
  }
  map<int, int> groupedByCnt;
  for (auto[x, y] : cnt) {
    groupedByCnt[y]++;
  }

  int res = n;
  int left = 0, right = n, rightCnt = (int) cnt.size();
  for (auto[x, y] : groupedByCnt) {
    res = min(res, left + right - rightCnt * x);
    left += x * y;
    right -= x * y;
    rightCnt -= y;
  }
  cout << res << endl;
}

int main() {
  int tests;
  cin >> tests;
  while (tests-- > 0) {
    solve();
  }
  return 0;
}

#include <bits/stdc++.h>

using namespace std;
using ll = long long;

void solve() {
  int n, m;
  cin >> n >> m;
  vector<ll> a(n);
  ll allSum = 0;
  vector<ll> pref;
  vector<int> ind;
  int curInd = 0;
  for (ll &e : a) {
    cin >> e;
    allSum += e;
    if (pref.empty() || allSum > pref.back()) {
      pref.push_back(allSum);
      ind.push_back(curInd);
    }
    curInd++;
  }
  for (int q = 0; q < m; q++) {
    ll x;
    cin >> x;
    if (pref.back() < x && allSum <= 0) {
      cout << -1 << " ";
      continue;
    }
    ll needTimes = 0;
    if (pref.back() < x) {
      needTimes = (x - pref.back() + allSum - 1) / allSum;
    }
    x -= needTimes * allSum;
    cout << needTimes * n + ind[lower_bound(pref.begin(), pref.end(), x) - pref.begin()] << " ";
  }
  cout << "\n";
}

int main() {
  int t;
  cin >> t;
  while (t--) {
    solve();
  }
}
